# CSV Line Parser

Here's a robust `parse_csv_line` that handles quoted fields with embedded commas, newlines, and escaped quotes (RFC 4180 style, where `""` inside a quoted field represents a literal `"`).

```python
def parse_csv_line(line: str) -> list[str]:
    """
    Parse a single CSV line into a list of fields.

    Handles:
      - Quoted fields: "..."
      - Embedded commas inside quoted fields
      - Embedded newlines inside quoted fields
      - Escaped quotes: "" inside a quoted field == literal "
      - Empty fields

    Raises:
      AssertionError: if the line is malformed (e.g. unterminated quote,
        comma after a closing quote, etc.)
    """
    assert isinstance(line, str), "line must be a string"

    fields: list[str] = []
    i = 0
    n = len(line)

    while True:
        # ---- parse one field ----
        if i < n and line[i] == '"':
            # ---- quoted field ----
            i += 1  # consume opening quote
            buf: list[str] = []
            while True:
                if i >= n:
                    raise AssertionError(
                        f"unterminated quoted field at position {i}"
                    )
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        # escaped quote -> literal "
                        buf.append('"')
                        i += 2
                    else:
                        # closing quote
                        i += 1
                        break
                else:
                    buf.append(ch)
                    i += 1
            fields.append("".join(buf))
        else:
            # ---- unquoted field: read until comma or end ----
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])

        # ---- separator or end? ----
        if i < n and line[i] == ',':
            i += 1  # consume comma, continue to next field
            continue
        else:
            break

    # ---- trailing comma => trailing empty field ----
    if i == n and line.endswith(','):
        fields.append('')

    return fields
```

## Tests

```python
def test_basic():
    assert parse_csv_line("a,b,c") == ["a", "b", "c"]

def test_empty_fields():
    assert parse_csv_line("a,,c") == ["a", "", "c"]
    assert parse_csv_line(",") == ["", ""]
    assert parse_csv_line("") == [""]

def test_embedded_comma():
    assert parse_csv_line('a,"b,c"') == ["a", "b,c"]
    assert parse_csv_line('"a,b",c') == ["a,b", "c"]

def test_embedded_newline():
    assert parse_csv_line('a,"b\nc"') == ["a", "b\nc"]

def test_escaped_quotes():
    assert parse_csv_line('"she said ""hi"""') == ['she said "hi"']
    assert parse_csv_line('"a""b"') == ['a"b']

def test_mixed():
    assert parse_csv_line('1,"Smith, John",NY') == \
        ["1", "Smith, John", "NY"]

def test_trailing_comma():
    assert parse_csv_line("a,b,") == ["a", "b", ""]

def test_no_trailing_comma():
    assert parse_csv_line("a,b") == ["a", "b"]

def test_unterminated_quote_raises():
    try:
        parse_csv_line('"abc')
        raise AssertionError("should have raised")
    except AssertionError:
        pass

def test_comma_after_quote_raises():
    try:
        parse_csv_line('"abc",,d')
        raise AssertionError("should have raised")
    except AssertionError:
        pass

if __name__ == "__main__":
    for name, fn in sorted(globals().items()):
        if name.startswith("test_") and callable(fn):
            fn()
    print("All tests passed.")
```

## Notes

- **Escaped quotes** use the standard `""` → `"` convention. If your data uses backslash-escaping (`\"`) instead, the quote-handling block would differ.
- **The trailing-comma check** is a bit conservative: it only appends an empty field when the line *ends* with a comma. A more lenient parser would treat any trailing comma as a field separator. Adjust based on your data.
